export default function ({ body }) {
  const raw = body?.youtubeUrl;
  if (typeof raw !== "string") throw Error("youtubeUrl is required");
  const m = raw.match(
      /^https:\/\/(?:www\.)?(?:youtu\.be\/([a-zA-Z0-9_-]{11})(?:[?&#/]|$)|(?:m\.)?youtube\.com\/(?:watch\?[^#]*\bv=|(?:shorts|embed)\/)([a-zA-Z0-9_-]{11})(?:[?&#/]|$))/i,
    ),
    id = m?.[1] ?? m?.[2];
  if (!id) throw Error("Invalid YouTube video URL");
  return {
    id,
    url: "https://www.youtube.com/watch?v=" + id,
    metadataUrl: "https://api.ytapi.dev/v1/videos/" + id + "/video-info",
    transcriptUrl: "https://api.ytapi.dev/v1/transcripts?video_id=" + id + "&format=segments",
  };
}

