export default function ({ id, url, metadata, transcript }) {
  if (
    metadata?.video_id !== id ||
    transcript?.video_id !== id ||
    typeof metadata.title !== "string" ||
    typeof metadata.description !== "string" ||
    !Array.isArray(transcript.segments) ||
    !transcript.segments.length ||
    transcript.segments.some((x) => typeof x.text !== "string")
  )
    throw Error("Missing or mismatched video data");
  const text = transcript.segments
    .map((x) => x.text)
    .join(" ")
    .trim();
  if (!text) throw Error("Transcript is empty");
  return { title: metadata.title, description: metadata.description, id, url, text };
}

