export default function ({ id, url, title, description, analysis }) {
  if (!analysis?.summary?.trim() || !Array.isArray(analysis.topics)) throw Error("Summary missing");
  return {
    response: {
      id,
      youtubeUrl: url,
      title,
      description,
      summary: analysis.summary,
      topics: analysis.topics,
    },
    notice: title + "\n" + url,
  };
}

