export default async function ({ id }, ctx) {
  const key = "youtube-notice:" + id,
    s = await ctx.state.get(key);
  if (s === "pending") throw Error("Inspect Telegram before retry");
  if (s === "done") return { key, skip: true };
  await ctx.state.set(key, "pending");
  return { key, skip: false };
}

